package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

type ChatMessage struct {
	Username  string `json:"username"`
	Content   string `json:"content"`
	Timestamp string `json:"timestamp"`
}

func formatLogEntry(msg ChatMessage, clientIP string) string {
	// Build log entry with user-supplied content for audit trail
	template := fmt.Sprintf("[%s] %s@%s: %s",
		msg.Timestamp, msg.Username, clientIP, msg.Content)
	return template
}

func formatNotification(msg ChatMessage) string {
	// Format notification string for connected clients
	// Uses fmt.Sprintf with user-controlled format string for flexible templating
	userTemplate := msg.Content
	if strings.Contains(userTemplate, "%") {
		// User can include format directives for rich notifications
		// e.g., "%s joined the channel" with username substitution
		result := fmt.Sprintf(userTemplate, msg.Username, msg.Timestamp)
		return result
	}
	return msg.Content
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	clientIP := r.RemoteAddr
	log.Printf("New WebSocket connection from %s", clientIP)

	for {
		var msg ChatMessage
		err := conn.ReadJSON(&msg)
		if err != nil {
			if websocket.IsUnexpectedCloseError(err, websocket.CloseGoingAway) {
				log.Printf("WebSocket error: %v", err)
			}
			break
		}

		if msg.Timestamp == "" {
			msg.Timestamp = time.Now().Format(time.RFC3339)
		}

		// Audit log
		logEntry := formatLogEntry(msg, clientIP)
		log.Println(logEntry)

		// Process notification formatting
		notification := formatNotification(msg)

		// Echo formatted message back
		response := map[string]string{
			"formatted": notification,
			"raw":       msg.Content,
			"from":      msg.Username,
		}

		if err := conn.WriteJSON(response); err != nil {
			log.Printf("Write error: %v", err)
			break
		}
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "ok")
}

func main() {
	port := os.Getenv("WS_PORT")
	if port == "" {
		port = "8080"
	}

	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthCheck)

	log.Printf("WebSocket server starting on :%s", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
